  // Phase 2: Global Escape key listener to close open modals
window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' || e.key === 'Esc') {
    const modal = document.getElementById('ai-connect-modal') || document.getElementById('connect-ai-modal');
    if (modal && (modal.style.display === 'flex' || modal.style.display === 'block')) {
      modal.style.display = 'none';
    }
  }
});

// Wire Dedicated AI Modal Open/Close
const aiModalBox = document.getElementById('ai-connect-modal') || document.getElementById('connect-ai-modal');
const openBtn = document.getElementById('btn-open-connect-ai');
const closeBtn = document.getElementById('btn-close-ai-modal') || document.getElementById('btn-close-modal');

if (openBtn && aiModalBox) {
  openBtn.addEventListener('click', function() {
    aiModalBox.style.display = 'flex';
  });
}
if (closeBtn && aiModalBox) {
  closeBtn.addEventListener('click', function() {
    aiModalBox.style.display = 'none';
  });
}
if (aiModalBox) {
  aiModalBox.addEventListener('click', function(e) {
    if (e.target === aiModalBox) {
      aiModalBox.style.display = 'none';
    }
  });
}
